/**
 * The font contract — what the shipped cuts PROMISE, enforced (sibling of theme-contract).
 *
 * The app face (Inter) carries scholarly transliteration (ʿ ā ḥ ṣ …), Hijri month names and the
 * animated degree readouts. This suite keeps three promises formal against the committed TTFs
 * in assets/fonts/ (generated by scripts/build-fonts.py):
 *
 *  1. COVERAGE — every non-ASCII codepoint that appears in a source string literal has a real
 *     glyph in every cut (no silent tofu when copy gains a new diacritic), plus a hardcoded
 *     floor so the promise can't weaken even if copy churns. Deliberate platform-fallback
 *     glyphs (ﷺ, ✓ — no Latin face carries them; the OS renders them today too) are allowlisted.
 *  2. FIGURES — the display face shapes lining-tabular digits with uniform advances, so the
 *     tally ramp (`useTallyUp`) can never jiggle horizontally mid-animation.
 *  3. SYNC — Face tokens (theme.ts), FontAssets keys (fonts.ts), the files on disk, and each
 *     file's real OS/2 weight all agree — a mismatch would silently fake-bold on Android.
 */

import { readdirSync, readFileSync } from 'node:fs';
import { basename, join } from 'node:path';
import { TextDecoder as NodeTextDecoder } from 'node:util';

import { describe, expect, it } from '@jest/globals';
import ts from 'typescript';

import { FontAssets } from '@/constants/fonts';
import { Face, Typography } from '@/constants/theme';

import type { Font } from 'fontkit';

// jest-expo installs Expo's WinterCG TextDecoder polyfill, which rejects the legacy 'ascii'
// label fontkit decodes name tables with — restore Node's spec-complete implementation before
// fontkit loads (hence the deferred require: a hoisted `import` would run before this line).
(globalThis as { TextDecoder?: unknown }).TextDecoder = NodeTextDecoder;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const fontkit = require('fontkit') as { openSync: (path: string) => Font };

const FONTS_DIR = join(__dirname, '../../../assets/fonts');
const SRC_DIR = join(__dirname, '../..');

/** Codepoints every cut may omit: rendered by deliberate platform fallback, never the app face. */
const ALLOWED_FALLBACK = new Set([
  0xfdfa, // ﷺ — Arabic ligature; falls back to the platform Arabic font (as it does today)
  0x2713, // ✓ — UI chrome; the 14pt utility tier is system-voiced anyway
  0x22ef, // ⋯ — midline ellipsis used by icon-adjacent affordances
]);

/** The scholarly floor — the transliteration house style + almanac symbols, spelled out so
 *  coverage can't silently narrow even if the live copy scan changes shape. */
const FLOOR = Array.from('ḥṣḍṭḤṢṬāīūĀʿʾ°·×–—…−‘’“”', (c) => c.codePointAt(0) as number);

const fonts = new Map(
  readdirSync(FONTS_DIR)
    .filter((f) => f.endsWith('.ttf'))
    .map((f) => [basename(f, '.ttf'), fontkit.openSync(join(FONTS_DIR, f))]),
);

function os2Weight(font: Font): number {
  return (font as unknown as { 'OS/2': { usWeightClass: number } })['OS/2'].usWeightClass;
}

function* walkSources(dir: string): Generator<string> {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    // Test files never render in the app — their describe/it names would pollute the repertoire.
    if (entry.isDirectory() && entry.name !== '__tests__') yield* walkSources(path);
    else if (entry.isFile() && /(?<!\.test)\.(ts|tsx)$/.test(entry.name)) yield path;
  }
}

/** Every string-literal / template / JSX-text character in src/, as NFD codepoints > ASCII —
 *  the app's LIVE repertoire, parsed with the TypeScript AST (comments never count). */
function liveRepertoire(): Set<number> {
  const out = new Set<number>();
  for (const file of walkSources(SRC_DIR)) {
    const source = ts.createSourceFile(
      file,
      readFileSync(file, 'utf8'),
      ts.ScriptTarget.Latest,
      /* setParentNodes */ false,
      file.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
    );
    const visit = (node: ts.Node) => {
      const isText =
        ts.isStringLiteral(node) ||
        ts.isNoSubstitutionTemplateLiteral(node) ||
        ts.isTemplateHead(node) ||
        ts.isTemplateMiddle(node) ||
        ts.isTemplateTail(node) ||
        ts.isJsxText(node);
      if (isText) {
        // Both forms matter: the precomposed codepoints RN actually renders (source is NFC),
        // and their NFD decompositions (normalizeName strips via NFD, so combining marks flow).
        for (const ch of node.text + node.text.normalize('NFD')) {
          const cp = ch.codePointAt(0) as number;
          if (cp > 0x7f) out.add(cp);
        }
      }
      ts.forEachChild(node, visit);
    };
    visit(source);
  }
  return out;
}

describe('glyph coverage', () => {
  const repertoire = [...liveRepertoire()].filter((cp) => !ALLOWED_FALLBACK.has(cp)).sort((a, b) => a - b);

  it('found the live repertoire (the scan itself must not silently go blind)', () => {
    expect(repertoire.length).toBeGreaterThan(20);
  });

  it.each([...fonts.keys()])('%s covers every codepoint used in source strings', (name) => {
    const font = fonts.get(name)!;
    const missing = repertoire.filter((cp) => !font.hasGlyphForCodePoint(cp));
    expect(missing.map((cp) => `U+${cp.toString(16).toUpperCase()} ${String.fromCodePoint(cp)}`)).toEqual([]);
  });

  it.each([...fonts.keys()])('%s covers the scholarly floor', (name) => {
    const font = fonts.get(name)!;
    const missing = FLOOR.filter((cp) => !font.hasGlyphForCodePoint(cp));
    expect(missing.map((cp) => String.fromCodePoint(cp))).toEqual([]);
  });
});

describe('figure features (the tally-jiggle contract)', () => {
  it('the display face shapes tabular digits with uniform advances', () => {
    const font = fonts.get(Typography.display.fontFamily)!;
    expect(font.availableFeatures).toEqual(expect.arrayContaining(['tnum']));
    const run = font.layout('0123456789', ['tnum']);
    const advances = new Set(run.glyphs.map((g) => g.advanceWidth));
    expect(advances.size).toBe(1);
  });
});

describe('token ↔ asset sync', () => {
  it('FontAssets keys are exactly the files on disk', () => {
    expect(new Set(Object.keys(FontAssets))).toEqual(new Set(fonts.keys()));
  });

  it('every Face value is a loadable FontAssets key', () => {
    for (const family of Object.values(Face)) {
      expect(Object.keys(FontAssets)).toContain(family);
      expect(fonts.has(family)).toBe(true);
    }
  });

  it('every file weight matches its name (no fake-bold seams)', () => {
    const wantByName: Record<string, number> = { Regular: 400, SemiBold: 600, Bold: 700 };
    for (const [name, font] of fonts) {
      const suffix = name.split('-')[1] ?? '';
      expect(wantByName[suffix]).toBeDefined();
      expect(os2Weight(font)).toBe(wantByName[suffix]);
    }
  });

  it('custom-face variants set NO fontWeight — the file IS the weight', () => {
    // On Android, fontWeight '700' beside a runtime-registered family buckets into the legacy
    // BOLD style, misses the custom face and silently falls back to Roboto (observed on-device:
    // the hero degrees rendered in the fallback). Weight lives in the per-weight file; the
    // style must not restate it.
    for (const [variant, style] of Object.entries(Typography)) {
      const family = (style as { fontFamily?: string }).fontFamily;
      if (!family) continue; // the system-voiced tier
      expect({ variant, loaded: fonts.has(family) }).toEqual({ variant, loaded: true });
      expect({ variant, weight: (style as { fontWeight?: string }).fontWeight }).toEqual({
        variant,
        weight: undefined,
      });
    }
  });
});
